-- S197 — OpenBible ancient places base load (own-tile map render).
-- Source: source-texts/maps-openbible/data/ancient.jsonl (openbible.info CC-BY).
-- We ship coordinates only and render on our own SVG/canvas tiles — no
-- copyrighted atlas plate. The dispersion/gathering overlay rides in
-- tool_annotations (tool='maps', 'dispersion-overlay' + 'region:israel').
-- Re-runnable: ON CONFLICT (place_id) DO UPDATE.

BEGIN;

CREATE TABLE IF NOT EXISTS maps_places (
    id         BIGSERIAL PRIMARY KEY,
    place_id   TEXT NOT NULL UNIQUE,         -- openbible ancient id
    name       TEXT,                         -- friendly_id
    lon        DOUBLE PRECISION NOT NULL,
    lat        DOUBLE PRECISION NOT NULL,
    kind       TEXT,                         -- settlement / natural / region / ...
    osis_refs  TEXT[] NOT NULL DEFAULT '{}'  -- verses that name this place
);
CREATE INDEX IF NOT EXISTS idx_maps_kind ON maps_places(kind);

ON CONFLICT (place_id) DO UPDATE SET name=EXCLUDED.name, lon=EXCLUDED.lon, lat=EXCLUDED.lat, kind=EXCLUDED.kind, osis_refs=EXCLUDED.osis_refs;

ON CONFLICT (place_id) DO UPDATE SET name=EXCLUDED.name, lon=EXCLUDED.lon, lat=EXCLUDED.lat, kind=EXCLUDED.kind, osis_refs=EXCLUDED.osis_refs;

ON CONFLICT (place_id) DO UPDATE SET name=EXCLUDED.name, lon=EXCLUDED.lon, lat=EXCLUDED.lat, kind=EXCLUDED.kind, osis_refs=EXCLUDED.osis_refs;

DO $v$ DECLARE n INT; BEGIN
  SELECT COUNT(*) INTO n FROM maps_places;
  RAISE NOTICE 'session197 maps: % places', n;
  IF n < 1268 THEN RAISE EXCEPTION 'maps load short: %', n; END IF;
END $v$;

COMMIT;
